import { describe, expect, it } from "vitest";
import {
  AUDIENCE_RULES,
  PLACE_RULES,
  TIER_HYPOTHESES,
  TRANSIT_REACH_KM,
  buildKnowledgeGraph,
} from "../src/services/knowledgeGraph";
import type { Dataset, Event, Hotel, Place, Venue } from "../src/types";

/**
 * The knowledge graph is generated by rules, not authored per event.
 *
 * These checks exist for that claim specifically: the same function must draw a graph for any
 * event, every relation must name the rule that produced it, and nothing may depend on an event's
 * name or id. A rule that only works for the event someone was looking at would fail here.
 */
const venue = (id: string, name: string, lng = 120.702, lat = 31.32): Venue => ({
  id,
  name,
  address: null,
  districtId: null,
  coordinates: {
    lng,
    lat,
    system: "GCJ-02",
    status: "Verified",
    sourceUrl: "https://ditu.amap.com/place/TEST",
  },
  districtDemo: false,
});

const event = (
  id: string,
  category: Event["category"],
  overrides: Partial<Event> = {},
): Event =>
  ({
    id,
    name: `活动 ${id}`,
    category,
    startDate: "2026-11-01",
    endDate: null,
    venueId: "v1",
    districtId: null,
    organizer: null,
    attendance: null,
    sponsor: null,
    demo: false,
    ...overrides,
  }) as Event;

const place = (
  id: string,
  kind: Place["kind"],
  subtype: string,
  lng: number,
  lat: number,
): Place => ({
  id,
  kind,
  subtype,
  name: `${subtype} ${id}`,
  address: null,
  city: "苏州市",
  district: "吴中区",
  coordinates: {
    lng,
    lat,
    system: "GCJ-02",
    status: "Verified",
    sourceUrl: "https://ditu.amap.com/place/" + id,
  },
  declaredType: "",
  sampledNearVenueId: "v1",
  sampledRadiusM: 1500,
  distanceToVenueKm: null,
});

const hotel = (
  id: string,
  tier: Hotel["tier"],
  lng = 120.703,
  lat = 31.321,
): Hotel => ({
  id,
  name: `酒店 ${id}`,
  address: null,
  districtId: null,
  districtDemo: false,
  coordinates: {
    lng,
    lat,
    system: "GCJ-02",
    status: "Verified",
    sourceUrl: "https://ditu.amap.com/place/" + id,
  },
  tier,
  tierLabel: { high: "高端", mid: "中端", comfort: "舒适" }[tier ?? "mid"],
});

// ~0.011° of latitude is 1.2 km, so the fixture distances below are deliberate.
const at = (kmNorth: number, kmEast = 0) => ({
  lng: 120.702 + kmEast / 94.5,
  lat: 31.32 + kmNorth / 111,
});

const dataset = (over: Partial<Dataset> = {}): Dataset =>
  ({
    events: [],
    venues: [venue("v1", "苏州文化艺术中心")],
    hotels: [],
    districts: [],
    places: [],
    evidence: [
      {
        id: "e1",
        entityId: "event",
        field: "venueId",
        value: "v1",
        status: "Verified",
        method: "test",
        sourceName: "官方来源",
        // effectiveStatus downgrades a Verified claim without a source URL, and the graph only
        // draws the venue edge for a claim that really is verified.
        sourceUrl: "https://example.invalid/venue",
        updatedAt: "2026-10-16T00:00:00Z",
      },
    ],
    updatedAt: "2026-10-16T00:00:00Z",
    ...over,
  }) as unknown as Dataset;

/** Every fixture event must have its venue reference verified for the chain to be drawn. */
const withEvent = (e: Event, over: Partial<Dataset> = {}): Dataset => {
  const base = dataset(over);
  base.events = [e];
  base.evidence = [
    ...base.evidence.map((row) => ({ ...row, entityId: e.id })),
  ];
  return base;
};

describe("the graph is generated for any event", () => {
  it("draws the same shape for two events that differ only in name and id", () => {
    const a = withEvent(event("a", "culture"));
    const b = withEvent(event("b", "culture"));
    b.events = [{ ...b.events[0], name: "完全不同的名字" }];
    const ga = buildKnowledgeGraph(a.events[0], a, { places: true, audience: true });
    const gb = buildKnowledgeGraph(b.events[0], b, { places: true, audience: true });
    expect(ga.nodes.map((n) => n.kind)).toEqual(gb.nodes.map((n) => n.kind));
    expect(ga.edges.map((e) => e.label)).toEqual(gb.edges.map((e) => e.label));
  });

  it("gives every node and edge the rule that produced it", () => {
    const data = withEvent(event("a", "sports"), {
      places: [place("p1", "restaurant", "咖啡厅", ...Object.values(at(0.3)) as [number, number])],
    });
    const graph = buildKnowledgeGraph(data.events[0], data, {
      places: true,
      audience: true,
      related: true,
    });
    expect(graph.nodes.length).toBeGreaterThan(3);
    expect(graph.nodes.every((n) => !!n.rule && !!n.reason)).toBe(true);
    expect(graph.edges.every((e) => !!e.rule && !!e.reason)).toBe(true);
  });

  it("is deterministic: the same event always yields the same graph", () => {
    const data = withEvent(event("a", "business"), {
      places: [
        place("p1", "restaurant", "中餐厅", ...Object.values(at(0.4)) as [number, number]),
        place("p2", "restaurant", "快餐厅", ...Object.values(at(0.2)) as [number, number]),
        place("p3", "transport", "地铁站", ...Object.values(at(0.5)) as [number, number]),
      ],
    });
    const first = buildKnowledgeGraph(data.events[0], data, { places: true, audience: true });
    const second = buildKnowledgeGraph(data.events[0], data, { places: true, audience: true });
    expect(second.nodes.map((n) => n.id)).toEqual(first.nodes.map((n) => n.id));
    expect(second.edges.map((e) => e.id)).toEqual(first.edges.map((e) => e.id));
  });
});

describe("audience rules", () => {
  const cases: Array<[Event["category"], string]> = [
    ["business", "商务差旅客群"],
    ["culture", "文化消费客群"],
    ["sports", "体育观赛客群"],
    ["education", "教育家庭客群"],
    ["folk", "民俗节庆客群"],
    ["government", "公共事务客群"],
    ["others", "综合消费客群"],
  ];

  it.each(cases)("maps %s to exactly one base segment", (category, segment) => {
    const data = withEvent(event("a", category));
    const graph = buildKnowledgeGraph(data.events[0], data, { audience: true });
    const audience = graph.nodes.filter((n) => n.kind === "Audience");
    expect(audience.map((n) => n.label)).toEqual([segment]);
    expect(audience[0].analytical).toBe(true);
    expect(
      graph.edges.find((e) => e.target === audience[0].id)?.analytical,
    ).toBe(true);
  });

  it("adds the multi-day rule only when the run actually spans days", () => {
    const oneDay = withEvent(event("a", "culture", { startDate: "2026-11-01", endDate: "2026-11-01" }));
    const threeDays = withEvent(
      event("a", "culture", { startDate: "2026-11-01", endDate: "2026-11-03" }),
    );
    const labels = (data: Dataset) =>
      buildKnowledgeGraph(data.events[0], data, { audience: true })
        .nodes.filter((n) => n.kind === "Audience")
        .map((n) => n.label);
    expect(labels(oneDay)).toEqual(["文化消费客群"]);
    expect(labels(threeDays)).toEqual(["文化消费客群", "多日住宿需求"]);
  });

  it("adds the scale rule only when a recorded attendance is large", () => {
    const small = withEvent(event("a", "sports", { attendance: 800 }));
    const large = withEvent(event("a", "sports", { attendance: 12_000 }));
    const labels = (data: Dataset) =>
      buildKnowledgeGraph(data.events[0], data, { audience: true })
        .nodes.filter((n) => n.kind === "Audience")
        .map((n) => n.label);
    expect(labels(small)).toEqual(["体育观赛客群"]);
    expect(labels(large)).toEqual(["体育观赛客群", "大规模聚集"]);
  });

  it("never invents a segment from a missing field", () => {
    const unknown = withEvent(
      event("a", "culture", { startDate: null, endDate: null, attendance: null }),
    );
    const graph = buildKnowledgeGraph(unknown.events[0], unknown, { audience: true });
    expect(graph.nodes.filter((n) => n.kind === "Audience").map((n) => n.label)).toEqual([
      "文化消费客群",
    ]);
  });

  it("keeps the audience layer out of the graph when it is switched off", () => {
    const data = withEvent(event("a", "business"));
    const graph = buildKnowledgeGraph(data.events[0], data, { audience: false });
    expect(graph.nodes.some((n) => n.kind === "Audience")).toBe(false);
  });

  it("states a trigger basis for every rule it ships", () => {
    AUDIENCE_RULES.forEach((rule) => {
      expect(rule.basis.length).toBeGreaterThan(0);
      expect(rule.detail.length).toBeGreaterThan(0);
      expect(TIER_HYPOTHESES[rule.segment]).toBeDefined();
    });
  });
});

describe("proximity rules for 餐饮 and 交通", () => {
  const base = (places: Place[]) =>
    withEvent(event("a", "business", { startDate: "2026-11-01", endDate: "2026-11-02" }), {
      places,
    });

  it("keeps a restaurant inside the 1.5 km reach and drops one outside it", () => {
    const data = base([
      place("near", "restaurant", "中餐厅", ...(Object.values(at(1.0)) as [number, number])),
      place("far", "restaurant", "中餐厅", ...(Object.values(at(3.0)) as [number, number])),
    ]);
    const graph = buildKnowledgeGraph(data.events[0], data, { places: true });
    const ids = graph.nodes.filter((n) => n.kind === "Restaurant").map((n) => n.id);
    expect(ids).toEqual(["near"]);
    expect(graph.edges.find((e) => e.target === "near")?.label).toMatch(/^餐饮 · 1\.0\d km$/);
    expect(PLACE_RULES[0].reachKm).toBe(1.5);
  });

  it("gives each transport subtype its own reach", () => {
    const data = base([
      place("metro", "transport", "地铁站", ...(Object.values(at(2.0)) as [number, number])),
      place("bus", "transport", "公交车站", ...(Object.values(at(0.6)) as [number, number])),
      place("bus_far", "transport", "公交车站", ...(Object.values(at(1.5)) as [number, number])),
      place("rail", "transport", "火车站", ...(Object.values(at(9.0)) as [number, number])),
      place("air", "transport", "机场", ...(Object.values(at(25.0)) as [number, number])),
      place("ferry", "transport", "港口码头", ...(Object.values(at(1.0)) as [number, number])),
    ]);
    const graph = buildKnowledgeGraph(data.events[0], data, { places: true });
    const ids = graph.nodes.filter((n) => n.kind === "Transport").map((n) => n.id).sort();
    // 港口码头 has no reach defined: it is not access to the venue, so it is never drawn.
    expect(ids).toEqual(["air", "bus", "metro", "rail"]);
    expect(TRANSIT_REACH_KM["公交车站"]).toBe(1);
    expect(TRANSIT_REACH_KM["机场"]).toBe(30);
  });

  it("draws nothing when a place has no coordinate", () => {
    const blind = { ...place("blind", "restaurant", "中餐厅", 0, 0), coordinates: null };
    const data = base([blind]);
    const graph = buildKnowledgeGraph(data.events[0], data, { places: true });
    expect(graph.nodes.some((n) => n.kind === "Restaurant")).toBe(false);
  });

  it("keeps the place layer out of the graph when it is switched off", () => {
    const data = base([
      place("near", "restaurant", "中餐厅", ...(Object.values(at(0.5)) as [number, number])),
    ]);
    const graph = buildKnowledgeGraph(data.events[0], data, { places: false });
    expect(graph.nodes.some((n) => n.kind === "Restaurant")).toBe(false);
  });
});

describe("the tier hypothesis is bounded by the hotels actually shown", () => {
  it("only connects a segment to tiers its own rule allows", () => {
    const data = withEvent(event("a", "business"), {
      hotels: [hotel("h-high", "high", ...Object.values(at(1.0)) as [number, number])],
    });
    const graph = buildKnowledgeGraph(data.events[0], data, { audience: true });
    const segment = graph.nodes.find((n) => n.label === "商务差旅客群")!;
    const tierEdges = graph.edges.filter((e) => e.rule === "audience_hotel_tier");
    expect(tierEdges.map((e) => e.target)).toEqual(["h-high"]);
    expect(tierEdges[0].source).toBe(segment.id);
    expect(tierEdges[0].analytical).toBe(true);
  });

  it("does not connect a segment to a tier its rule excludes", () => {
    const data = withEvent(event("a", "education"), {
      hotels: [hotel("h-high", "high", ...Object.values(at(1.0)) as [number, number])],
    });
    const graph = buildKnowledgeGraph(data.events[0], data, { audience: true });
    expect(graph.edges.filter((e) => e.rule === "audience_hotel_tier")).toEqual([]);
  });

  it("does not invent a hotel that is not in this event's graph", () => {
    const data = withEvent(event("a", "business"), {
      hotels: [hotel("far", "high", 120.9, 31.6)], // ~22 km away
    });
    const graph = buildKnowledgeGraph(data.events[0], data, { audience: true });
    expect(graph.edges.filter((e) => e.rule === "audience_hotel_tier")).toEqual([]);
  });
});

describe("every rule that fired is reported", () => {
  it("reports the rules behind the drawn relations, with counts", () => {
    const data = withEvent(event("a", "business", { startDate: "2026-11-01", endDate: "2026-11-02" }), {
      places: [
        place("p1", "restaurant", "咖啡厅", ...(Object.values(at(0.3)) as [number, number])),
        place("p2", "transport", "地铁站", ...(Object.values(at(0.4)) as [number, number])),
      ],
    });
    const graph = buildKnowledgeGraph(data.events[0], data, { places: true, audience: true });
    const ids = graph.fired.map((r) => r.id);
    expect(ids).toContain("near_restaurant");
    expect(ids).toContain("near_transit");
    expect(ids).toContain("audience_business");
    expect(ids).toContain("audience_multi_day");
    graph.fired.forEach((rule) => {
      expect(rule.relations).toBeGreaterThan(0);
      expect(rule.detail.length).toBeGreaterThan(0);
    });
    expect(graph.fired.find((r) => r.id === "near_restaurant")?.relations).toBe(1);
  });
});
